{{ config(materialized='table') }}

with
pit_deal_deal_detail_ranked as (
    select
        deal_hk,
        effective_from,
        dense_rank() over (partition by deal_hk order by hashdiff_basis_version desc) as dpf_version_rank
    from {{ ref("investment__deal_vault__sat_deal_detail") }}
),
pit_deal_deal_detail_scoped as (
    select
        deal_hk,
        effective_from
    from pit_deal_deal_detail_ranked
    where dpf_version_rank = 1
),
pit_deal_deal_pipeline_ranked as (
    select
        deal_hk,
        effective_from,
        dense_rank() over (partition by deal_hk order by hashdiff_basis_version desc) as dpf_version_rank
    from {{ ref("investment__deal_vault__sat_deal_pipeline") }}
),
pit_deal_deal_pipeline_scoped as (
    select
        deal_hk,
        effective_from
    from pit_deal_deal_pipeline_ranked
    where dpf_version_rank = 1
),
pit_deal_spine as (
    select distinct
        deal_hk,
        effective_from as as_of
    from pit_deal_deal_detail_scoped
    union distinct
    select distinct
        deal_hk,
        effective_from as as_of
    from pit_deal_deal_pipeline_scoped
),
pit_deal_deal_detail as (
    select
        pit_deal_spine.deal_hk as deal_hk,
        pit_deal_spine.as_of as as_of,
        max(pit_deal_deal_detail_stored.effective_from) as deal_detail_effective_from
    from pit_deal_spine
    left join pit_deal_deal_detail_scoped as pit_deal_deal_detail_stored
        on pit_deal_deal_detail_stored.deal_hk = pit_deal_spine.deal_hk
        and pit_deal_deal_detail_stored.effective_from <= pit_deal_spine.as_of
    group by pit_deal_spine.deal_hk, pit_deal_spine.as_of
),
pit_deal_deal_pipeline as (
    select
        pit_deal_spine.deal_hk as deal_hk,
        pit_deal_spine.as_of as as_of,
        max(pit_deal_deal_pipeline_stored.effective_from) as deal_pipeline_effective_from
    from pit_deal_spine
    left join pit_deal_deal_pipeline_scoped as pit_deal_deal_pipeline_stored
        on pit_deal_deal_pipeline_stored.deal_hk = pit_deal_spine.deal_hk
        and pit_deal_deal_pipeline_stored.effective_from <= pit_deal_spine.as_of
    group by pit_deal_spine.deal_hk, pit_deal_spine.as_of
),
pit_deal_joined as (
    select
        pit_deal_spine.deal_hk as deal_hk,
        pit_deal_spine.as_of as as_of,
        pit_deal_deal_detail.deal_detail_effective_from as deal_detail_effective_from,
        pit_deal_deal_pipeline.deal_pipeline_effective_from as deal_pipeline_effective_from
    from pit_deal_spine
    left join pit_deal_deal_detail
        on pit_deal_deal_detail.deal_hk = pit_deal_spine.deal_hk and pit_deal_deal_detail.as_of = pit_deal_spine.as_of
    left join pit_deal_deal_pipeline
        on pit_deal_deal_pipeline.deal_hk = pit_deal_spine.deal_hk and pit_deal_deal_pipeline.as_of = pit_deal_spine.as_of
)

select
    cast(deal_hk as {{ dpf_type('string') }}) as deal_hk,
    cast(as_of as {{ dpf_type('date') }}) as as_of,
    cast(deal_detail_effective_from as {{ dpf_type('date') }}) as deal_detail_effective_from,
    cast(deal_pipeline_effective_from as {{ dpf_type('date') }}) as deal_pipeline_effective_from
from pit_deal_joined
